// Pythia8 driver for showering MC@NLO events generated by MG5_aMC.
//
// Usage:  Pythia8.exe <command file> [<locked settings file>]
//
// The command file is written by MG5_aMC (madgraph/various/mcatnlo_shower.py).
// The optional second file lists the settings that the MC@NLO subtraction
// requires. They are checked after initialisation, so that a tune, a plugin
// or a later line in the command file cannot silently change them.
//
// Compile-time options (set by the Makefile in this directory):
//   MG5_ANALYSIS  a Fortran analysis (pyabeg/pyanal/pyaend) is linked and is
//                 fed through the /HEPEVT/ common block;
//   MG5_HEPMC     0, 2 or 3: no event file, or HepMC2 ascii events written
//                 with the HepMC2 or with the HepMC3 library.
//
// Exit status: 0 success, 1 set-up error, 2 too many failed events,
//              3 the locked settings were changed.

#include "Pythia8/Pythia.h"
#include "Pythia8Plugins/CombineMatchingInput.h"

#include <cmath>
#include <cstdlib>
#include <fstream>
#include <iostream>
#include <sstream>
#include <string>
#include <vector>

#ifndef MG5_HEPMC
#define MG5_HEPMC 0
#endif

#if MG5_HEPMC == 3
#include "Pythia8Plugins/HepMC3.h"
#elif MG5_HEPMC == 2
#include "Pythia8Plugins/HepMC2.h"
#include "HepMC/GenEvent.h"
#include "HepMC/IO_GenEvent.h"
#endif

#ifdef MG5_ANALYSIS
#include "LHEFRead.h"
#endif

using namespace Pythia8;

//==========================================================================
// Fortran analysis interface.

#ifdef MG5_ANALYSIS

extern "C" {
  extern struct { double EVWGT; } cevwgt_;
  // The /HEPEVT/ common block. Its size depends on NMXHEP, so it is
  // addressed through offsets computed at run time.
  extern char hepevt_[];
  void pyabeg_(int&, char(*)[wgts_info_len_used]);
  void pyaend_(double&);
  void pyanal_(int&, double*);
}

// Length of the weight labels, provided by HwU.f. Analyses without HwU
// (e.g. TopDrawer) use this weak default.
extern "C" __attribute__((weak)) int get_wgts_info_len(void) {
  return wgts_info_len_used;
}

// NMXHEP of the analysis: 4000 in include/HEPMC.INC. An analysis using a
// different value must call hepmc_set_max_number_entries(NMXHEP) in pyabeg.
static int mg5NmxHep = 4000;

extern "C" void hepmc_set_max_number_entries_(const int& entries) {
  if (entries < 1) {
    std::cerr << "Error: unsupported HEPEVT capacity " << entries << "\n";
    std::exit(1);
  }
  mg5NmxHep = entries;
}

// Fill /HEPEVT/ with the Pythia event record (entry 0, the system, is
// skipped, so that HEPEVT index i is Pythia index i). Same content as the
// HepMC2 IO_HEPEVT path used before, without requiring HepMC.
static bool fillHepevt(const Event& event, int eventNumber) {
  int n = event.size() - 1;
  if (n > mg5NmxHep) return false;
  int  nmx    = mg5NmxHep;
  int* ip     = reinterpret_cast<int*>(hepevt_);
  int* isthep = ip + 2;
  int* idhep  = isthep + nmx;
  int* jmohep = idhep + nmx;
  int* jdahep = jmohep + 2 * nmx;
  double* phep = reinterpret_cast<double*>(jdahep + 2 * nmx);
  double* vhep = phep + 5 * nmx;
  ip[0] = eventNumber;
  ip[1] = n;
  for (int i = 1; i <= n; ++i) {
    const Particle& p = event[i];
    int k = i - 1;
    isthep[k] = p.statusHepMC();
    idhep[k]  = p.id();
    int m1 = p.mother1(), m2 = p.mother2();
    if (m2 == 0) m2 = m1;
    if (m2 < m1) std::swap(m1, m2);
    jmohep[2 * k] = m1;
    jmohep[2 * k + 1] = m2;
    int d1 = p.daughter1(), d2 = p.daughter2();
    if (d2 == 0) d2 = d1;
    if (d2 < d1) std::swap(d1, d2);
    jdahep[2 * k] = d1;
    jdahep[2 * k + 1] = d2;
    phep[5 * k]     = p.px();
    phep[5 * k + 1] = p.py();
    phep[5 * k + 2] = p.pz();
    phep[5 * k + 3] = p.e();
    phep[5 * k + 4] = p.m();
    vhep[4 * k]     = p.xProd();
    vhep[4 * k + 1] = p.yProd();
    vhep[4 * k + 2] = p.zProd();
    vhep[4 * k + 3] = p.tProd();
  }
  return true;
}

#endif

//==========================================================================
// Verification of the settings required by the MC@NLO subtraction.

static std::string lower(std::string text) {
  for (size_t i = 0; i < text.size(); ++i) text[i] = std::tolower(text[i]);
  return text;
}

static std::string trim(const std::string& text) {
  size_t b = text.find_first_not_of(" \t\r\n");
  if (b == std::string::npos) return "";
  size_t e = text.find_last_not_of(" \t\r\n");
  return text.substr(b, e - b + 1);
}

static bool sameNumber(double a, double b) {
  return std::fabs(a - b) <= 1e-9 * std::max(1., std::max(std::fabs(a),
                                                            std::fabs(b)));
}

static bool asFlag(const std::string& value, bool& result) {
  std::string v = lower(value);
  if (v == "on" || v == "true" || v == "yes" || v == "1") result = true;
  else if (v == "off" || v == "false" || v == "no" || v == "0") result = false;
  else return false;
  return true;
}

// Compare one locked entry; on failure describe the actual value.
static bool checkSetting(Pythia& pythia, const std::string& key,
  const std::string& value, std::string& actual) {
  std::string k = lower(key);
  size_t colon = k.find(':');
  // Particle data, e.g. 5:m0.
  if (colon != std::string::npos && colon > 0
      && k.find_first_not_of("-0123456789") == colon) {
    int id = std::atoi(k.substr(0, colon).c_str());
    std::string prop = k.substr(colon + 1);
    double got;
    if (prop == "m0") got = pythia.particleData.m0(id);
    else if (prop == "mwidth") got = pythia.particleData.mWidth(id);
    else { actual = "unsupported particle property"; return false; }
    std::ostringstream os; os << got; actual = os.str();
    return sameNumber(got, std::atof(value.c_str()));
  }
  Settings& s = pythia.settings;
  if (s.isFlag(key)) {
    bool want, got = s.flag(key);
    actual = got ? "on" : "off";
    return asFlag(value, want) && want == got;
  }
  if (s.isMode(key)) {
    int got = s.mode(key);
    std::ostringstream os; os << got; actual = os.str();
    return got == std::atoi(value.c_str());
  }
  if (s.isParm(key)) {
    double got = s.parm(key);
    std::ostringstream os; os << got; actual = os.str();
    return sameNumber(got, std::atof(value.c_str()));
  }
  if (s.isWord(key)) {
    actual = s.word(key);
    return actual == value;
  }
  actual = "setting not known to this Pythia version";
  return false;
}

static int verifyLocked(Pythia& pythia, const std::string& file) {
  std::ifstream in(file.c_str());
  if (!in) {
    std::cerr << "Error: cannot read the locked settings file " << file << "\n";
    return 1;
  }
  int nChecked = 0, nFailed = 0;
  std::string line;
  while (std::getline(in, line)) {
    size_t hash = line.find('!');
    if (hash != std::string::npos) line = line.substr(0, hash);
    size_t eq = line.find('=');
    if (eq == std::string::npos) continue;
    std::string key = trim(line.substr(0, eq)), value = trim(line.substr(eq + 1));
    if (key.empty()) continue;
    std::string actual;
    ++nChecked;
    if (!checkSetting(pythia, key, value, actual)) {
      ++nFailed;
      std::cerr << "MG5_MCATNLO_CONTRACT mismatch: " << key << " is " << actual
                << ", the MC@NLO subtraction requires " << value << "\n";
    }
  }
  if (nFailed > 0) {
    std::cout << "MG5_MCATNLO_CONTRACT FAILED (" << nFailed << " of "
              << nChecked << " settings differ)" << std::endl;
    return 3;
  }
  std::cout << "MG5_MCATNLO_CONTRACT OK (" << nChecked
            << " settings verified)" << std::endl;
  return 0;
}

//==========================================================================

int main(int argc, char* argv[]) {

  if (argc < 2) {
    std::cerr << "Usage: " << argv[0]
              << " <command file> [<locked settings file>]\n";
    return 1;
  }
  std::string cmdFile = argv[1];
  std::string lockedFile = (argc > 2) ? argv[2] : "";
  std::string hepmcFile = "Pythia8.hep";

  Pythia pythia;
  if (!pythia.readFile(cmdFile)) {
    std::cerr << "Error: invalid or unsupported Pythia settings in "
              << cmdFile << "\n";
    return 1;
  }

  long nTotal  = pythia.mode("Main:numberOfEvents");
  long nShower = pythia.mode("Main:spareMode1");
  std::string evtNorm = pythia.word("Main:spareWord1");
  int maxErrors = pythia.mode("Main:timesAllowErrors");
  if (nShower <= 0 || nTotal <= 0) {
    std::cerr << "Error: invalid numbers of events in " << cmdFile << "\n";
    return 1;
  }
  // Normalisation of the event weights, following event_norm in the run
  // card (Main:spareWord1):
  //   average, bias: the weights average to the cross section, as in the LHE
  //                  file; they are kept unchanged ('bias' events have
  //                  varying weights, still averaging to the cross section);
  //   sum:           the weights sum to the cross section. The LHE weights sum
  //                  to it over the nTotal events of the file (of this job);
  //                  showering nShower of them, they are rescaled by
  //                  nTotal/nShower.
  // HepMC has no convention of its own: the cross section is written in each
  // event (GenCrossSection), which is what analysis tools such as Rivet use.
  bool sumNorm = (lower(evtNorm) == "sum");
  double weightFactor = sumNorm ? double(nTotal) / double(nShower) : 1.;
  // Contribution of one event to the cross-section estimate.
  double normEvent = sumNorm
    ? double(nTotal) / double(nShower) : 1. / double(nShower);

  // FxFx merging.
  bool isFxFx = pythia.flag("JetMatching:doFxFx");
  CombineMatchingInput combined;
  if (isFxFx) {
    double qCut  = pythia.parm("JetMatching:qCut");
    double qCutME = pythia.parm("JetMatching:qCutME");
    if (qCut <= qCutME || qCut <= 0.) {
      std::cerr << "Error: the FxFx merging scale Qcut (shower card) = " << qCut
                << " must be larger than ptj (run card) = " << qCutME << "\n";
      return 1;
    }
#if PYTHIA_VERSION_INTEGER >= 8300
    combined.setHook(pythia);
#else
    UserHooks* matching = combined.getHook(pythia);
    if (!matching) {
      std::cerr << "Error: could not set up the FxFx jet matching\n";
      return 1;
    }
    pythia.setUserHooksPtr(matching);
#endif
  }

  if (!pythia.init()) {
    std::cerr << "Error: could not initialise Pythia" << std::endl;
    return 1;
  }

  if (!lockedFile.empty()) {
    int status = verifyLocked(pythia, lockedFile);
    if (status != 0) return status;
  }

#ifdef MG5_ANALYSIS
  int nWeights;
  char weightLabels[1024][wgts_info_len_used];
  double weights[1024];
  MyReader reader(pythia.word("Beams:LHEF"));
  reader.lhef_read_wgtsinfo_(nWeights, weightLabels);
  pyabeg_(nWeights, weightLabels);
  long nLHEread = 0;
  long nAnalysed = 0, nTooLarge = 0;
#endif

#if MG5_HEPMC == 3
  HepMC3::Pythia8ToHepMC3 toHepMC;
  toHepMC.set_store_pdf(false);
  toHepMC.set_store_proc(false);
  toHepMC.set_store_xsec(false);
  HepMC3::WriterAsciiHepMC2 hepmcOut(hepmcFile);
  std::shared_ptr<HepMC3::GenRunInfo> runInfo
    = std::make_shared<HepMC3::GenRunInfo>();
  // All the weights of the events (nominal and variations), as named by
  // Pythia8.
  runInfo->set_weight_names(pythia.info.weightNameVector());
  hepmcOut.set_run_info(runInfo);
#elif MG5_HEPMC == 2
  HepMC::Pythia8ToHepMC toHepMC;
  toHepMC.set_store_pdf(false);
  toHepMC.set_store_proc(false);
  toHepMC.set_store_xsec(false);
  HepMC::IO_GenEvent hepmcOut(hepmcFile.c_str(), std::ios::out);
#endif

  int  nPrintLHA = 1;
  long nAccepted = 0, nErrors = 0;
  double sigmaSum = 0.;
  int status = 0;

  // Read nShower events from the LHE file. Events vetoed by Pythia (e.g. by
  // the FxFx merging) or lost in errors still count, so that the sum of the
  // normalised weights of the accepted events estimates the cross section.
  while (pythia.info.nTried() < nShower) {
    if (!pythia.next()) {
      if (pythia.info.atEndOfFile()) break;
      if (++nErrors > maxErrors) {
        std::cerr << "Error: too many failed events (" << nErrors
                  << "); allowed: " << maxErrors << "\n";
        status = 2;
        break;
      }
      continue;
    }
    ++nAccepted;

    if (nPrintLHA > 0 && pythia.info.isLHA()) {
      pythia.LHAeventList();
      pythia.info.list();
      pythia.process.list();
      pythia.event.list();
      --nPrintLHA;
    }

    double weight = pythia.info.weight();
    sigmaSum += weight * normEvent;
    // Running estimate of the total cross section (pb).
    double sigmaNow = sigmaSum * double(nShower)
      / double(std::max(1L, long(pythia.info.nTried())));

#if MG5_HEPMC == 3
    HepMC3::GenEvent hepmcEvent(runInfo, HepMC3::Units::GEV, HepMC3::Units::MM);
    toHepMC.fill_next_event(pythia, &hepmcEvent);
    // All weights (nominal and variations) follow event_norm.
    for (size_t i = 0; i < hepmcEvent.weights().size(); ++i)
      hepmcEvent.weights()[i] *= weightFactor;
    std::shared_ptr<HepMC3::GenCrossSection> xsec
      = std::make_shared<HepMC3::GenCrossSection>();
    hepmcEvent.set_cross_section(xsec);
    xsec->set_cross_section(sigmaNow, pythia.info.sigmaErr() * 1e9);
    hepmcOut.write_event(hepmcEvent);
#elif MG5_HEPMC == 2
    HepMC::GenEvent* hepmcEvent = new HepMC::GenEvent();
    toHepMC.fill_next_event(pythia, hepmcEvent);
    // All weights (nominal and variations) follow event_norm.
    HepMC::WeightContainer& eventWeights = hepmcEvent->weights();
    if (eventWeights.size() == 0) eventWeights.push_back(weight);
    for (size_t i = 0; i < eventWeights.size(); ++i)
      eventWeights[i] *= weightFactor;
    HepMC::GenCrossSection xsec;
    xsec.set_cross_section(sigmaNow, pythia.info.sigmaErr() * 1e9);
    hepmcEvent->set_cross_section(xsec);
    hepmcOut << hepmcEvent;
    delete hepmcEvent;
#endif

#ifdef MG5_ANALYSIS
    // Keep the weight reader in step with the events read by Pythia,
    // including those rejected before this one.
    for (long nTried = pythia.info.nTried(); nLHEread < nTried; ++nLHEread)
      reader.lhef_read_wgts_(weights);
    if (!fillHepevt(pythia.event, int(nAnalysed + 1))) {
      ++nTooLarge;
      continue;
    }
    ++nAnalysed;
    cevwgt_.EVWGT = weight;
    weights[0] = weight;
    pyanal_(nWeights, weights);
    if (nAnalysed % 5000 == 0) {
      // Intermediate output; the histograms are averaged over the events
      // analysed, and rescaled for the events vetoed or lost by Pythia.
      double norm = ((lower(evtNorm) == "sum") ? double(nTotal) : 1.)
        * double(nAnalysed) / double(pythia.info.nTried());
      pyaend_(norm);
    }
#endif
  }

  long nRead = pythia.info.nTried();
#ifdef MG5_ANALYSIS
  if (nAnalysed > 0) {
    double norm = ((lower(evtNorm) == "sum") ? double(nTotal) : 1.)
      * double(nAnalysed) / double(nRead);
    pyaend_(norm);
  }
  if (nTooLarge > 0)
    std::cerr << "Warning: " << nTooLarge << " events larger than the HEPEVT"
              << " capacity (" << mg5NmxHep << ") were not analysed\n";
#endif

  pythia.stat();

  if (nRead < nShower && status == 0)
    std::cerr << "Warning: the event file ended after " << nRead
              << " events (" << nShower << " requested)\n";
  // Cross section after the shower: the weights of the accepted events,
  // averaged over all the events read. Events vetoed by Pythia (FxFx
  // merging) or lost in errors count with zero weight, so that with FxFx
  // this is the merged cross section, smaller than the NLO one.
  double sigma = sigmaSum * double(nShower) / double(std::max(1L, nRead));
  std::cout << "MG5_MCATNLO_SUMMARY read=" << nRead << " showered=" << nAccepted
            << " failed=" << nErrors << " sigma=" << sigma << std::endl;
  if (isFxFx) {
    std::cout << "\nCross section, including FxFx merging is: "
              << sigma << "\n";
  }
  return status;
}
